**2. JavaScript (Sorting Logic)**

```javascript
function sortTable(columnIndex) {
  let table = document.querySelector("table");
  let tbody = table.querySelector("tbody");
  let rows = Array.from(tbody.querySelectorAll("tr")); // Convert to array

  rows.sort((a, b) => {
    let valA = a.querySelectorAll("td")[columnIndex].textContent.trim();
    let valB = b.querySelectorAll("td")[columnIndex].textContent.trim();

    // Alphanumeric comparison (handles numbers and strings)
    if (isNaN(parseFloat(valA)) && isNaN(parseFloat(valB))) {
      // Both are strings
      return valA.localeCompare(valB);
    } else if (!isNaN(parseFloat(valA)) && !isNaN(parseFloat(valB))) {
      // Both are numbers
      return parseFloat(valA) - parseFloat(valB);
    } else {
      // Mixed types - prioritize numbers
      return (parseFloat(valA) || 0) - (parseFloat(valB) || 0);
    }
  });

  // Clear the table body and append sorted rows
  tbody.innerHTML = "";
  rows.forEach(row => tbody.appendChild(row));
}
```

