      return (
        <ChildComponent name="Alice" age={30} />
      );
    }

    function ChildComponent(props) {
      return (
        <div>
          Hello, my name is {props.name} and I am {props.age} years old.
        </div>
      );
    }
    ```

*   **When to Use:**
