import { service } from '@glimmer/core';
import { tracked } from '@glimmer/tracked';

export default class CsvDownloader extends Component {
  @service()
  worker;

  @tracked({get(this) { return null;}}) data = null;
  @tracked({get(this) { return '';}}) error = '';
  @tracked({get(this) { return false;}}) isLoading = false;
  @tracked({get(this) { return 0;}}) progress = 0;

  constructor(owner, args) {
    super(owner, args);
    this.worker = this.owner.factoryFor('worker'); // Assuming you'll register a worker service
  }

  async downloadCsv(url) {
    this.isLoading = true;
    this.error = '';
    this.data = null;
    this.progress = 0;

    try {
      const worker = this.worker.create();

      worker.onmessage = (event) => {
        const { type, data } = event.data;

        if (type === 'progress') {
          this.progress = data;
        } else if (type === 'data') {
          this.data = data;
          this.isLoading = false;
        }
      };

      worker.onerror = (error) => {
        this.error = error.message;
        this.isLoading = false;
      };

      worker.postMessage({ url });

    } catch (e) {
      this.error = `Error creating worker: ${e.message}`;
      this.isLoading = false;
    }
  }
}
